using System.Collections.Concurrent;
using System.Security.Cryptography;
using System.Text;

namespace HitMe.Server.Protocol;

/// <summary>Phase 5 replaces this draft verifier with a Supabase JWT verifier.</summary>
public interface IAuthVerifier
{
    bool TryVerify(string? token, out PlayerIdentity identity, out string error);
}

public sealed record PlayerIdentity(string PlayerId, string DisplayName);

/// <summary>
/// Development-only guest identity issuer. A client supplies only guest:&lt;display name&gt;;
/// the stable opaque player id is generated by the server and cannot be chosen by the client.
/// </summary>
public sealed class FakeAuthVerifier : IAuthVerifier
{
    private readonly ConcurrentDictionary<string, PlayerIdentity> issued = new(StringComparer.Ordinal);

    public bool TryVerify(string? token, out PlayerIdentity identity, out string error)
    {
        identity = null!;
        if (string.IsNullOrWhiteSpace(token)) { error = "auth_required"; return false; }
        if (!token.StartsWith("guest:", StringComparison.Ordinal) || token.Length <= "guest:".Length || token.StartsWith("guest:expired:", StringComparison.Ordinal))
        { error = "auth_invalid"; return false; }

        var displayName = SanitizeDisplayName(token["guest:".Length..]);
        if (string.IsNullOrEmpty(displayName)) { error = "auth_invalid"; return false; }
        identity = issued.GetOrAdd(token, _ => new PlayerIdentity("g_" + RandomId(), displayName));
        error = string.Empty;
        return true;
    }

    public static string SanitizeDisplayName(string input)
    {
        var safe = new string(input.Where(character => !char.IsControl(character)).ToArray()).Trim();
        return safe.Length <= 24 ? safe : safe[..24];
    }

    private static string RandomId()
    {
        Span<byte> bytes = stackalloc byte[16];
        RandomNumberGenerator.Fill(bytes);
        return Convert.ToHexString(bytes).ToLowerInvariant();
    }
}
